// Generated by scripts/build.mjs from site/assets/js/mca-applications/main.js. Do not edit; run `npm run build`.
(() => {
'use strict';

// ---- mca-applications/data.js
/* ---------------- Data pools and configuration ---------------- */
const FIRST = ["Marcus", "Tanya", "Priya", "Elena", "Devin", "Carla", "Omar", "Lena", "Gregory", "Naomi", "Hector", "Sofia", "Andre", "Maya", "Victor", "Rachel", "Dmitri", "Aisha", "Liam", "Bianca"];
const LAST = ["Delgado", "Okonkwo", "Nakamura", "Vasquez", "Whitfield", "Brennan", "Castellano", "Petrov", "Adebayo", "Sorensen", "Mercado", "Halloran", "Yamamoto", "Okafor", "Donnelly", "Rivera", "Kowalski", "Fontaine", "Ashford", "Salinas"];
const BIZ_CORE = ["Riverstone", "Bluefield", "Cedar Peak", "Harborview", "Ironwood", "Summit Lane", "Maple Crest", "Northgate", "Silverbrook", "Coastal Pine", "Granite Hollow", "Westwind", "Brightwater", "Stonebridge", "Lakeside"];
const BIZ_KIND = [["Outdoor Supply", "Gear Co."], ["Auto Works", "Tire & Service"], ["Catering Group", "Kitchen"], ["Logistics", "Freight"], ["Construction", "Builders"], ["Medical Supply", "Health"], ["Print Solutions", "Print Shop"], ["Landscaping", "Lawn Care"], ["Fitness Studios", "Gym"], ["Bakery", "Bake Shop"], ["Plumbing Services", "Plumbers"], ["Electric Co.", "Electricians"]];
const ISO = ["Beacon Capital Partners LLC", "Summit Lane Funding Group, Inc.", "Apex Merchant Advisors", "Keystone Funding Solutions", "Lighthouse Capital Brokers", "Vanguard Business Advance"];
const USES = ["Inventory purchase and expansion", "Equipment upgrade and working capital", "Hiring and payroll support", "Marketing and store renovation", "Debt consolidation and growth", "New location buildout"];
const STREETS = ["Harborview Boulevard", "Industrial Parkway", "Cedar Hollow Lane", "Palmetto Ridge Court", "Maple Crest Drive", "Stonebridge Way", "Lakeshore Avenue", "Granite Hollow Road", "Westwind Terrace", "Brightwater Circle"];
const LINE2 = ["Suite 310", "Building C, Floor 2", "Apt 4B", "Unit 7", "Suite 120", "Floor 3", "Unit 12", "Suite 205", ""];
const CITIES = [["Springfield", "OH", "45504"], ["Tampa", "FL", "33607"], ["Austin", "TX", "78704"], ["Denver", "CO", "80205"], ["Raleigh", "NC", "27604"], ["Portland", "OR", "97214"], ["Phoenix", "AZ", "85016"], ["Columbus", "OH", "43215"], ["Sacramento", "CA", "95814"], ["Nashville", "TN", "37210"]];

const OWNER_COUNTS = [1, 2, 3, 4];
const EXECUTIVE_TITLES = ["CEO", "CFO", "COO", "VP"];
const ENTITY_TYPES = [
  { label: "Limited Liability Company (LLC)", suffix: " LLC", minOwners: 1, maxOwners: 4, titles: ["Managing Member", "Owner", "Principal", ...EXECUTIVE_TITLES] },
  { label: "Corporation (C-Corp)", suffix: " Corporation", minOwners: 1, maxOwners: 4, titles: ["President", "Chief Executive Officer", "Owner", "Principal", ...EXECUTIVE_TITLES] },
  { label: "S-Corporation", suffix: " Corporation", minOwners: 1, maxOwners: 4, titles: ["President", "Chief Executive Officer", "Owner", "Principal", ...EXECUTIVE_TITLES] },
  { label: "Sole Proprietorship", suffix: "", minOwners: 1, maxOwners: 1, fullOwnershipOnly: true, titles: ["Owner", "Principal"] },
  { label: "Partnership", suffix: " Partnership", minOwners: 2, maxOwners: 4, titles: ["Managing Partner", "Owner", "Principal"] },
];

/**
 * Config: {bizName, ownerCount: 1..4, owners: [{name, percentage}], applicationDate: "YYYY-MM-DD", seed}.
 * Input percentages are decimal strings; blank means automatic. Ownership math
 * uses integer hundredths of a percent (100% = 10000) to avoid rounding drift.
 * Address: {street1, street2, city, state, zip}.
 * Owner: {first, last, pct, ssn, dob, email, cell, home, title, addr: Address}.
 * Application: {seed, legal, dba, entity, fein, email, phone, start, years,
 *   biz: Address, amountCents, iso, use, appDate, owners: Owner[]}.
 * Dates are ISO calendar dates; money is integer cents and output pct values
 * have at most two decimal places. The renderer escapes all generated text.
 */

// ---- shared/random.js
// FNV-1a hashes UTF-16 text into the Mulberry32 state. Preserve this sequence
// and callers' draw order so existing seeds continue to reproduce their data.
function createRandom(seed) {
  let state = 2166136261;
  for (let index = 0; index < seed.length; index++) {
    state = Math.imul(state ^ seed.charCodeAt(index), 16777619) >>> 0;
  }
  return () => {
    state = (state + 0x6D2B79F5) >>> 0;
    let value = Math.imul(state ^ (state >>> 15), state | 1);
    value ^= value + Math.imul(value ^ (value >>> 7), value | 61);
    return ((value ^ (value >>> 14)) >>> 0) / 4294967296;
  };
}

const randomInt = (rng, min, max) => Math.floor(rng() * (max - min + 1)) + min;
const pick = (rng, values) => values[randomInt(rng, 0, values.length - 1)];

function createSeed() {
  return [...crypto.getRandomValues(new Uint32Array(2))]
    .map(number => number.toString(16).padStart(8, '0')).join('');
}

// ---- shared/formatting.js
const pad = (value, length = 2) => String(value).padStart(length, '0');

// Both generators represent money in integer cents.
const formatMoney = cents => `${cents < 0 ? '-' : ''}$${(Math.abs(cents) / 100).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;

const escapeHtml = value => String(value).replace(/[&<>"']/g, char => ({
  '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;',
})[char]);

// ---- shared/validation.js
// Keep field identifiers on errors so each controller can resolve its own inputs.
function configError(field, message) {
  return Object.assign(new Error(message), { field });
}

// ---- mca-applications/generation.js
const formatName = owner => [owner.first, owner.last].filter(Boolean).join(" ");
const formatDate = isoDate => `${isoDate.slice(5, 7)}/${isoDate.slice(8, 10)}/${isoDate.slice(0, 4)}`;
const DAY_MS = 24 * 60 * 60 * 1000;

function validateConfig(config) {
  if (typeof config.bizName !== "string" || config.bizName.length > 160) throw configError("bizNameOverride", "Business name must contain no more than 160 characters.");
  if (!OWNER_COUNTS.includes(config.ownerCount)) throw configError("ownerCount", "Choose between one and four owners.");
  if (!Array.isArray(config.owners) || config.owners.length !== config.ownerCount) throw configError("ownerCount", "Provide settings for each selected owner.");
  config.owners.forEach((owner, index) => {
    if (!owner || typeof owner.name !== "string" || owner.name.length > 160) throw configError(`ownerName_${index}`, `Owner ${index + 1}'s name must contain no more than 160 characters.`);
  });
  analyzeOwnership(config.owners);
  const value = config.applicationDate;
  const parsed = typeof value === "string" && /^\d{4}-\d{2}-\d{2}$/.test(value) ? new Date(`${value}T00:00:00Z`) : null;
  if (!parsed || Number.isNaN(parsed.getTime()) || parsed.getUTCFullYear() < 1900 || parsed.toISOString().slice(0, 10) !== value) {
    throw configError("applicationDate", "Choose a valid application date between January 1, 1900 and December 31, 9999.");
  }
  if (typeof config.seed !== "string" || !config.seed.trim() || config.seed.length > 200) throw configError("seed", "Enter a generation seed of 1–200 characters.");
}

function completedYears(start, end) {
  return Number(end.slice(0, 4)) - Number(start.slice(0, 4)) - (end.slice(5) < start.slice(5) ? 1 : 0);
}

function yearsBefore(isoDate, years) {
  const [year, month, day] = isoDate.split("-").map(Number);
  const targetYear = year - years;
  const lastDay = new Date(Date.UTC(targetYear, month, 0)).getUTCDate();
  return new Date(Date.UTC(targetYear, month - 1, Math.min(day, lastDay)));
}

// Select real calendar days with the requested range of completed anniversaries.
function pastDate(applicationDate, minYears, maxYears, rng) {
  const firstDay = yearsBefore(applicationDate, maxYears + 1).getTime() / DAY_MS + 1;
  const lastDay = yearsBefore(applicationDate, minYears).getTime() / DAY_MS;
  return new Date(randomInt(rng, firstDay, lastDay) * DAY_MS).toISOString().slice(0, 10);
}

/* ---------------- Identity and ownership generation ---------------- */
function emailSlug(value, fallback, separator = "", maxLength = 63) {
  const slug = value.normalize("NFKD").replace(/[\u0300-\u036f]/g, "").toLowerCase()
    .replace(/[^a-z0-9]+/g, separator).replace(/^\.+|\.+$/g, "").slice(0, maxLength).replace(/\.+$/g, "");
  return slug || fallback;
}

function phone(rng) {
  return `(555) ${randomInt(rng, 100, 999)}-${pad(randomInt(rng, 0, 9999), 4)}`;
}

function makeAddress(rng) {
  const [city, state, zip] = pick(rng, CITIES);
  return { street1: `${randomInt(rng, 50, 9999)} ${pick(rng, STREETS)}`, street2: pick(rng, LINE2), city, state, zip };
}

function analyzeOwnership(owners) {
  let manualTotal = 0;
  const basisPoints = owners.map((owner, index) => {
    const value = owner.percentage;
    if (value === '') return null;
    if (typeof value !== 'string' || !/^(?:\d+(?:\.\d{0,2})?|\.\d{1,2})$/.test(value)) {
      throw configError(`ownerPercentage_${index}`, `Enter a percentage with up to two decimal places for owner ${index + 1}, or leave it blank for automatic.`);
    }
    const amount = Math.round(Number(value) * 100);
    if (!Number.isFinite(amount) || amount <= 0 || amount > 10000) {
      throw configError(`ownerPercentage_${index}`, `Owner ${index + 1}'s ownership must be greater than 0% and no more than 100%.`);
    }
    manualTotal += amount;
    if (manualTotal > 10000) throw configError(`ownerPercentage_${index}`, 'Total ownership cannot exceed 100%.');
    return amount;
  });
  const automaticCount = basisPoints.filter(value => value === null).length;
  const remaining = 10000 - manualTotal;
  if (remaining < automaticCount) {
    throw configError(`ownerPercentage_${basisPoints.indexOf(null)}`, 'Leave at least 0.01% for each automatic owner, or reduce the owner count.');
  }
  return { basisPoints, manualTotal, automaticCount, remaining };
}

function ownershipSplit(owners, rng) {
  const { basisPoints, automaticCount, remaining: unassigned } = analyzeOwnership(owners);
  let remaining = unassigned;
  let ownersLeft = automaticCount;
  return basisPoints.map(value => {
    if (value !== null) return value / 100;
    // Keep all automatic shares positive, even when only a fraction remains.
    const minimum = remaining >= ownersLeft * 500 ? 500 : 1;
    const maximum = Math.min(remaining - (ownersLeft - 1) * minimum, Math.floor(remaining / ownersLeft) + 1000);
    const amount = ownersLeft === 1 ? remaining : randomInt(rng, minimum, maximum);
    remaining -= amount;
    ownersLeft--;
    return amount / 100;
  });
}

function makeOwner(percentage, index, config, entity, rng) {
  let first = pick(rng, FIRST);
  let last = pick(rng, LAST);
  const nameOverride = config.owners[index].name.trim();
  if (nameOverride) {
    const [given, ...family] = nameOverride.split(/\s+/);
    first = given;
    last = family.join(" ");
  }
  const email = `${emailSlug(formatName({ first, last }), `owner${index + 1}`, ".", 64)}@example.com`;
  return {
    first, last, pct: percentage,
    ssn: `${randomInt(rng, 100, 899)}-${randomInt(rng, 10, 99)}-${randomInt(rng, 1000, 9999)}`,
    dob: pastDate(config.applicationDate, 34, 61, rng),
    email, cell: phone(rng), home: phone(rng), title: pick(rng, entity.titles), addr: makeAddress(rng),
  };
}

/* ---------------- Pure application entry point ---------------- */
function generateApplication(config, rng) {
  validateConfig(config);
  rng ??= createRandom(config.seed);
  const core = pick(rng, BIZ_CORE);
  const kind = pick(rng, BIZ_KIND);
  const ownership = analyzeOwnership(config.owners);
  const includesFullOwnership = ownership.automaticCount > 0 || ownership.manualTotal === 10000;
  const entity = pick(rng, ENTITY_TYPES.filter(type => config.ownerCount >= type.minOwners && config.ownerCount <= type.maxOwners
    && (!type.fullOwnershipOnly || includesFullOwnership)));
  const legal = config.bizName.trim() || `${core} ${kind[0]}${entity.suffix}`;
  const start = pastDate(config.applicationDate, 5, 18, rng);
  const owners = ownershipSplit(config.owners, rng).map((percentage, index) => makeOwner(percentage, index, config, entity, rng));
  return {
    seed: config.seed, legal, dba: `${core} ${kind[1]}`, entity: entity.label,
    fein: `${randomInt(rng, 10, 99)}-${randomInt(rng, 1000000, 9999999)}`,
    email: `billing@${emailSlug(legal, "business")}.example.com`, phone: phone(rng),
    start, years: completedYears(start, config.applicationDate), biz: makeAddress(rng),
    amountCents: randomInt(rng, 25, 500) * 100000, iso: pick(rng, ISO), use: pick(rng, USES),
    appDate: config.applicationDate, owners,
  };
}

// ---- mca-applications/rendering.js
// Rows describe document fields; values are always text, never trusted markup.
function renderFields(rows) {
  return rows.map(row => `<div class="form-row" style="--columns:${row.length}">${row.map(([label, value]) =>
        `<dl class="form-field"><dt class="lbl">${escapeHtml(label)}</dt><dd class="val">${value === '' || value == null ? '&nbsp;' : escapeHtml(value)}</dd></dl>`
      ).join('')}</div>`).join('');
}

function ownerHeading(index, total) {
  return total === 1 ? 'Owner — Primary Guarantor'
    : `Owner ${index + 1} — ${index === 0 ? 'Primary Guarantor' : 'Co-Guarantor'}`;
}

function renderOwner(owner, index, total) {
  return `<section class="owner-block"><h4 class="who">${escapeHtml(ownerHeading(index, total))}</h4>${renderFields([
        [['First Name', owner.first], ['Last Name', owner.last], ['Ownership %', `${owner.pct}%`]],
        [['SSN', owner.ssn], ['Date of Birth', formatDate(owner.dob)], ['Email', owner.email]],
        [['Cell Phone', owner.cell], ['Home Phone', owner.home], ['Title', owner.title]],
        [['Home Address (Line 1)', owner.addr.street1], ['Home Address (Line 2)', owner.addr.street2]],
        [['City', owner.addr.city], ['State', owner.addr.state], ['ZIP', owner.addr.zip]],
      ])}</section>`;
}

function renderSignature(owner, index, total, applicationDate) {
  const name = escapeHtml(formatName(owner));
  return `<section class="signature-block"><h4 class="who">${escapeHtml(ownerHeading(index, total))}</h4>
      <div class="sig-row">
        <div><span class="lbl">Authorized Owner Signature</span><div class="sig-line"><span class="sig-name">${name}</span></div><div class="sig-cap">Signature of Owner / Guarantor</div></div>
        <div><span class="lbl">Date</span><div class="sig-line">${escapeHtml(applicationDate)}</div><div class="sig-cap">Date Signed</div></div>
      </div>
      <div class="sig-row">
        <div><span class="lbl">Printed Name</span><div class="sig-line">${name}</div><div class="sig-cap">Printed Name</div></div>
        <div><span class="lbl">Title</span><div class="sig-line">${escapeHtml(owner.title)}</div><div class="sig-cap">Title</div></div>
      </div>
    </section>`;
}

function renderApplication(application) {
  const applicationDate = formatDate(application.appDate);
  return `<header class="doc-header">
      <h2>Merchant Cash Advance Application</h2>
      <div class="sub">Business Funding Application &mdash; Confidential</div>
      <div class="synthetic">SYNTHETIC TEST DOCUMENT</div>
    </header>
    <div class="iso-bar"><div><strong>Submitted by ISO / Broker:</strong> ${escapeHtml(application.iso)}</div>
      <div class="application-date"><strong>Application Date:</strong> ${applicationDate}</div></div>
    <section><h3 class="sec-head">Business / Customer Information</h3>${renderFields([
        [['Legal Business Name', application.legal], ['DBA / Trade Name', application.dba]],
        [['Entity Type', application.entity], ['FEIN / EIN', application.fein]],
        [['Business Email', application.email], ['Business Phone', application.phone]],
        [['Business Start Date', formatDate(application.start)], ['Years in Business', application.years]],
        [['Street Address (Line 1)', application.biz.street1], ['Street Address (Line 2)', application.biz.street2]],
        [['City', application.biz.city], ['State', application.biz.state], ['ZIP', application.biz.zip]],
      ])}</section>
    <section><h3 class="sec-head">Funding Request</h3>${renderFields([
        [['Amount Requested', formatMoney(application.amountCents)], ['ISO / Broker Name', application.iso], ['Use of Funds', application.use]],
      ])}</section>
    <section class="owners-section"><h3 class="sec-head">Owner / Guarantor Information</h3>
      ${application.owners.map((owner, index) => renderOwner(owner, index, application.owners.length)).join('')}</section>
    <section class="signature-section"><div class="authorization-intro"><h3 class="sec-head">Authorization &amp; Signature${application.owners.length === 1 ? '' : 's'}</h3>
      <p class="attest">By signing below, the undersigned owner(s) and guarantor(s) certify that all information provided
        in this application is true, complete, and accurate. The undersigned authorizes ${escapeHtml(application.iso)} and its
        funding partners to obtain business and personal credit reports, verify bank and financial
        information, and contact references in connection with this funding request. This authorization
        shall remain in effect for the duration of the application review.</p></div>
      ${application.owners.map((owner, index) => renderSignature(owner, index, application.owners.length, applicationDate)).join('')}
    </section>
    <footer class="foot">${escapeHtml(application.legal)} &mdash; Merchant Cash Advance Application<br>
      <strong class="synthetic">SYNTHETIC TEST DOCUMENT.</strong> All data is fictitious.</footer>`;
}

// ---- shared/ui.js
function fillSelect(select, choices, selected) {
  select.replaceChildren(...choices.map(({ value, label }) => new Option(label, String(value))));
  select.value = String(selected);
}

// Controllers supply field lookup, including aliases and dynamically added rows.
// Existing help remains associated when an error is added or cleared.
function createFeedback({ form, status, error, resolveField }) {
  function setStatus(message, tone = '') {
    status.textContent = message;
    status.dataset.tone = tone;
  }

  function showError(message, field) {
    error.textContent = message;
    form.querySelectorAll('[aria-invalid]').forEach(input => {
      input.removeAttribute('aria-invalid');
      const descriptions = (input.getAttribute('aria-describedby') || '')
        .split(' ').filter(id => id && id !== error.id);
      if (descriptions.length) input.setAttribute('aria-describedby', descriptions.join(' '));
      else input.removeAttribute('aria-describedby');
    });
    const input = field ? resolveField(field) : null;
    if (message && input) {
      input.setAttribute('aria-invalid', 'true');
      input.setAttribute('aria-describedby', `${input.getAttribute('aria-describedby') || ''} ${error.id}`.trim());
      input.focus();
    }
  }

  return { setStatus, showError };
}

// ---- mca-applications/main.js
/* ---------------- Application state and controls ---------------- */
const state = { draft: null, result: null, appliedSignature: '', printing: false };
const ui = Object.fromEntries([
  'generatorForm', 'settings', 'bizNameOverride', 'ownerCount', 'ownerControls', 'ownershipStatus', 'applicationDate',
  'seed', 'btnGen', 'btnPrint', 'status', 'error', 'seedInfo', 'generatedSeed', 'page',
].map(id => [id, document.getElementById(id)]));

const { setStatus, showError } = createFeedback({
  form: ui.generatorForm,
  status: ui.status,
  error: ui.error,
  resolveField: field => ui[field] || (field && document.getElementById(field)),
});

function readDraft() {
  return {
    bizName: ui.bizNameOverride.value.trim(), owners: readOwnerControls(),
    ownerCount: Number(ui.ownerCount.value), applicationDate: ui.applicationDate.value, seed: ui.seed.value.trim(),
  };
}

function readOwnerControls() {
  return [...ui.ownerControls.querySelectorAll('.owner-card:not([hidden])')].map(card => {
    const percentage = card.querySelector('[data-owner-percentage]');
    return {
      name: card.querySelector('[data-owner-name]').value.trim(),
      // Browsers expose incomplete number entries as an empty value. They
      // must fail validation rather than silently becoming automatic shares.
      percentage: percentage.validity.badInput ? 'invalid' : percentage.value.trim(),
    };
  });
}

function initializeOwnerControls() {
  const cards = OWNER_COUNTS.map((_, index) => {
    const card = document.createElement('fieldset');
    card.className = 'owner-card';
    card.innerHTML = `<legend>Owner ${index + 1}${index === 0 ? ' — Primary signer' : ''}</legend><div class="fields">
      <div class="field"><label for="ownerName_${index}">Name</label><input id="ownerName_${index}" data-owner-name
        type="text" placeholder="Random owner name" maxlength="160"></div>
      <div class="field"><label for="ownerPercentage_${index}">Ownership (%)</label><input id="ownerPercentage_${index}" data-owner-percentage
        type="number" min="0.01" max="100" step="0.01" placeholder="Automatic" aria-describedby="ownershipHint ownershipStatus"></div>
    </div>`;
    return card;
  });
  ui.ownerControls.replaceChildren(...cards);
  updateOwnerControls();
}

function updateOwnerControls() {
  // Keep inactive rows in the DOM so names, percentages, and even unfinished
  // input survive decreasing and increasing the owner count.
  [...ui.ownerControls.children].forEach((card, index) => {
    card.hidden = index >= Number(ui.ownerCount.value);
    card.disabled = card.hidden;
  });
  updateOwnershipStatus();
}

function updateOwnershipStatus() {
  try {
    const { manualTotal, automaticCount, remaining } = analyzeOwnership(readOwnerControls());
    ui.ownershipStatus.textContent = automaticCount
      ? `${manualTotal / 100}% entered · ${automaticCount} automatic owner${automaticCount === 1 ? '' : 's'} share ${remaining / 100}%.`
      : `Total ownership: ${manualTotal / 100}%.`;
    ui.ownershipStatus.dataset.tone = '';
  } catch (error) {
    ui.ownershipStatus.textContent = error.message;
    ui.ownershipStatus.dataset.tone = 'warning';
  }
}

function hasPendingSettings() {
  return JSON.stringify(state.draft) !== state.appliedSignature;
}

function canPrint() {
  return Boolean(state.result) && !hasPendingSettings() && !state.printing;
}

function updateControls() {
  ui.settings.disabled = state.printing;
  ui.btnPrint.disabled = !canPrint();
}

function readyStatus() {
  if (!state.result) return 'Choose your settings and generate an application.';
  const { owners, entity, appDate } = state.result;
  return `${owners.length} owner${owners.length === 1 ? '' : 's'} · ${entity} · ${formatDate(appDate)}`;
}

function draftChanged(event) {
  if (state.printing) return;
  if (event.target.id === 'ownerCount') updateOwnerControls();
  else if (event.target.matches('[data-owner-percentage]')) updateOwnershipStatus();
  state.draft = readDraft();
  showError('');
  const pending = hasPendingSettings();
  setStatus(pending ? 'Settings changed—generate to apply.' : readyStatus(), pending ? 'warning' : '');
  updateControls();
}

function generatePreview(event) {
  event?.preventDefault();
  if (state.printing) return;
  state.draft = readDraft();
  showError('');
  try {
    const seed = state.draft.seed || createSeed();
    const result = generateApplication({ ...state.draft, seed });
    const html = renderApplication(result);
    // Publish only after validation, generation, and rendering all succeed.
    ui.page.innerHTML = html;
    state.result = result;
    state.appliedSignature = JSON.stringify(state.draft);
    ui.generatedSeed.textContent = result.seed;
    ui.seedInfo.hidden = false;
    setStatus(readyStatus());
  } catch (error) {
    showError(error.message || 'Could not generate the application. Check your settings and try again.', error.field);
    setStatus('Generation did not complete. Check the settings above.', 'warning');
  }
  updateControls();
}

function printApplication() {
  if (!canPrint()) return;
  showError('');
  state.printing = true;
  updateControls();
  try { window.print(); }
  catch (error) { showError(`Printing could not start. ${error.message || 'Please try again.'}`); }
  finally {
    state.printing = false;
    updateControls();
  }
}

function initialize() {
  fillSelect(ui.ownerCount, OWNER_COUNTS.map(count => ({ value: String(count), label: String(count) })), '1');
  initializeOwnerControls();
  const today = new Date();
  ui.applicationDate.value = `${today.getFullYear()}-${pad(today.getMonth() + 1)}-${pad(today.getDate())}`;
  ui.generatorForm.addEventListener('input', draftChanged);
  ui.generatorForm.addEventListener('submit', generatePreview);
  ui.btnPrint.addEventListener('click', printApplication);
  generatePreview();
}

initialize();
})();
